import heapq


class Solution:
    def minMeetingRooms(self, intervals: list[list[int]]) -> int:
        intervals.sort()                         # by start time: O(n log n)
        ends = []                                # min-heap of end times, one per room
        for start, end in intervals:
            if ends and ends[0] <= start:        # earliest-ending room is free (touching is fine)
                heapq.heappop(ends)              # reuse it
            heapq.heappush(ends, end)            # O(log n) per meeting
        return len(ends)                         # rooms ever needed at once
